// Route + validate gateway request. No LLM here.
const b = $input.first().json;
const tool = b.tool;
const allowed = ['web-search','product-search','product-details','vendor-search','price-retrieval'];
if (!allowed.includes(tool)) throw new Error('Unknown tool: ' + tool + '. Allowed: ' + allowed.join(','));
if (['web-search','product-search','vendor-search'].includes(tool) && !(b.query && String(b.query).trim()) && !b.serpapi_product_id) throw new Error(tool + ' requires query or serpapi_product_id');
if (tool === 'product-details' && !(b.url || b.serpapi_product_id)) throw new Error('product-details requires url or serpapi_product_id');
return [{ tool, query: b.query ?? null, url: b.url ?? null, serpapi_product_id: b.serpapi_product_id ?? null, max_results: Math.min(b.max_results ?? 8, 20) }];

// Normalize ANY provider response into BuyWise envelopes. Filter Amazon/Flipkart. No mocks.
const now = new Date().toISOString();
const EXCL = ['amazon.', 'flipkart.'];
const excluded = (u) => EXCL.some((h) => String(u || '').toLowerCase().includes(h));
const items = $input.all().map((i) => i.json);
const env = (source, source_url, data, confidence) => ({ source, source_url, retrieved_at: now, data_status: data && Object.values(data).some((v) => v === 'unavailable') ? 'PARTIAL' : 'LIVE', confidence, data, error: null, retryable: false });
const unav = (source, error, retryable = true) => ({ source, source_url: null, retrieved_at: now, data_status: 'UNAVAILABLE', confidence: 0, data: null, error: String(error), retryable });
const out = [];
for (const it of items) {
  if (it?.shopping_results) {
      for (const s of it.shopping_results.filter((x) => (x?.link || x?.product_link) && !excluded(x.link || x.product_link))) {
        const filled = [s.title, s.source, s.price, s.rating].filter((v) => v !== undefined && v !== null).length;
        out.push({ source: 'serpapi_shopping', source_url: String(s.link || s.product_link || '').replace(/ /g, '%20'), /*ENC-SERPI*/ retrieved_at: now, data_status: filled >= 3 ? 'LIVE' : 'PARTIAL', confidence: Math.min(0.5 + filled * 0.07, 0.9), data: { product_name: s.title ?? 'unavailable', merchant_name: s.source ?? 'unavailable', price: s.price ?? 'unavailable', currency: 'unavailable', rating: typeof s.rating === 'number' ? s.rating : 'unavailable', review_count: Number.isInteger(s.reviews) ? s.reviews : 'unavailable', serpapi_product_id: s.product_id ?? 'unavailable' }, error: null, retryable: false });
      }
    } else if (it?.results) { for (const r of it.results.filter((x) => x?.url && !excluded(x.url))) out.push(env('tavily_search', r.url, { title: r.title ?? 'unavailable', snippet: r.content ?? 'unavailable' }, 0.65)); }
  else if (it?.itemSummaries) { for (const s of it.itemSummaries.filter((x) => x?.itemWebUrl && !excluded(x.itemWebUrl))) out.push(env('ebay_browse_api', s.itemWebUrl, { title: s.title ?? 'unavailable', itemId: s.itemId ?? 'unavailable', price: s.price?.value ?? 'unavailable', currency: s.price?.currency ?? 'unavailable', condition: s.condition ?? 'unavailable', seller: s.seller?.username ?? 'unavailable' }, 0.85)); }
  else if (it?.title || it?.price) { if (!excluded(it.itemWebUrl)) out.push(env('ebay_browse_api', it.itemWebUrl ?? null, { title: it.title ?? 'unavailable', price: it.price?.value ?? 'unavailable', currency: it.price?.currency ?? 'unavailable' }, 0.9)); }
  else if (it?.error || it?.statusCode >= 400) { out.push(unav('provider', it.error ?? ('HTTP ' + it.statusCode), true)); }
}
if (!out.length) return [{ json: unav('tool-gateway', 'No verifiable (non-excluded) results from configured providers', false) }];
return out.map((e) => ({ json: e }));
